{
  "done": false,
  "tool": "manage_backends",
  "args": {
    "name": "Vendor SLA Data",
    "url": "http://localhost:7804",
    "operation": "add",
    "widgets_json": {
      "breach_metric": {
        "name": "Open Breaches",
        "description": "Count of open SLA breaches.",
        "endpoint": "/breach-count",
        "type": "metric",
        "w": 6,
        "h": 4,
        "params": [
          {
            "paramName": "desk_view",
            "type": "text",
            "label": "Desk View",
            "value": "summary",
            "description": "Which posture view the metric shows."
          }
        ]
      },
      "vendor_sla_table": {
        "name": "Vendor SLA Status",
        "description": "Vendor SLA state with breach flags.",
        "endpoint": "/vendor-sla",
        "type": "table",
        "w": 20,
        "h": 9,
        "params": [
          {
            "paramName": "status",
            "type": "text",
            "label": "Status",
            "options": [
              "Open",
              "Escalated",
              "Resolved"
            ],
            "value": "Open",
            "description": "Status filter"
          }
        ],
        "data": {
          "columnsDefs": [
            {
              "field": "vendor",
              "headerName": "Vendor",
              "cellDataType": "text"
            },
            {
              "field": "status",
              "headerName": "Status",
              "cellDataType": "text",
              "renderFn": "titleCase"
            },
            {
              "field": "latency_ms",
              "headerName": "Latency (ms)",
              "cellDataType": "number"
            },
            {
              "field": "breach",
              "headerName": "Breach",
              "cellDataType": "boolean"
            }
          ]
        }
      },
      "sla_newsfeed": {
        "name": "Vendor Notices",
        "description": "Vendor incident notices feed.",
        "endpoint": "/vendor-notices",
        "type": "newsfeed",
        "w": 12,
        "h": 10
      }
    }
  }
}

